<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit(1);
require dirname(__DIR__).'/app/bootstrap.php';
use App\Core\Database;
use App\Services\TranslationCompletenessValidator;
if(($GLOBALS['db_config']['database']??'')!=='saradeeeb_dev')throw new RuntimeException('Tests require the isolated development database.');
$passed=0;$failures=[];$pdo=Database::pdo();$validator=new TranslationCompletenessValidator();
function translationExpect(bool $ok,string $label):void{global $passed,$failures;if($ok)$passed++;else{$failures[]=$label;echo "FAIL: {$label}\n";}}
function sourceRow():array{return['title'=>'البيت المهجور','excerpt'=>'قصة عن بيت مهجور في آخر القرية.','content'=>'<p>دخل سامر البيت عند منتصف الليل.</p><p>وسمع صوتًا غريبًا خلف الباب.</p>','image_alt'=>'باب البيت القديم','image_caption'=>'البيت المهجور في ضوء القمر','seo_description'=>'قصة غامضة عن البيت المهجور','og_description'=>'قصة غامضة للقراءة'];}
function targetRow():array{return['title'=>'The Abandoned House','excerpt'=>'A story about an abandoned house at the edge of the village.','content'=>'<p>The visitor entered the house at midnight.</p><p>He heard a strange voice behind the door.</p>','image_alt'=>'The old house door','image_caption'=>'The abandoned house in moonlight','seo_description'=>'A mysterious story about the abandoned house','og_description'=>'A mysterious story to read'];}
function hasIssue(array $report,string $type,?string $field=null):bool{foreach($report['issues']??[] as $issue)if(($issue['type']??'')===$type&&($field===null||($issue['field']??'')===$field))return true;return false;}

$pdo->beginTransaction();
try{
    $source=sourceRow();$target=targetRow();
    $clean=$validator->inspect($source,$target,'ar','en',[],true);translationExpect($clean['state']==='passed'&&$clean['blocking']===0,'complete English translation passes');
    $case=$target;$case['title']='';$r=$validator->inspect($source,$case,'ar','en',[],true);translationExpect($r['state']==='incomplete'&&hasIssue($r,'missing','title'),'missing title blocks publication');
    $case=$target;$case['excerpt']='';$r=$validator->inspect($source,$case,'ar','en',[],true);translationExpect($r['state']==='incomplete'&&hasIssue($r,'missing','excerpt'),'empty excerpt blocks publication');
    $case=$target;$case['content']=$source['content'];$r=$validator->inspect($source,$case,'ar','en',[],true);translationExpect($r['blocking']>0&&hasIssue($r,'copied_source','content'),'copied source body blocks publication');
    $case=$target;$case['content']='<p>Samer entered the house at midnight.</p><p>وسمع صوتًا غريبًا خلف الباب.</p>';$r=$validator->inspect($source,$case,'ar','en',[],true);translationExpect($r['blocking']>0&&hasIssue($r,'copied_segment','content'),'untranslated source paragraph is identified by location');
    $case=$target;$case['content']='<p>Samer entered البيت at midnight.</p><p>He heard a strange voice behind the door.</p>';$r=$validator->inspect($source,$case,'ar','en',[],true);translationExpect($r['state']==='needs_review'&&hasIssue($r,'retained_words','content'),'single retained source-language word is flagged for review');
    $case=$target;$case['content']='<p>This is an English paragraph وفيها كلمات عربية ظاهرة.</p><p>He heard a voice.</p>';$r=$validator->inspect($source,$case,'ar','en',[],true);translationExpect($r['state']==='needs_review'&&hasIssue($r,'language_signal','content'),'mixed Arabic and English text is flagged');
    $case=$target;$case['content']='<p>Une nuit, il entendit une voix étrange.</p><p>He heard a voice.</p>';$r=$validator->inspect($source,$case,'ar','en',[],true);translationExpect($r['state']==='needs_review'&&hasIssue($r,'language_signal','content'),'mixed French and English text is flagged beyond script matching');
    $case=$target;$case['content']='<p>Он услышал странный голос в доме.</p><p>He heard a voice.</p>';$r=$validator->inspect($source,$case,'ar','en',[],true);translationExpect($r['state']==='needs_review'&&hasIssue($r,'language_signal','content'),'mixed Russian and English text is flagged');
    $case=$target;$case['seo_description']='TODO translate this';$r=$validator->inspect($source,$case,'ar','en',[],true);translationExpect($r['state']==='incomplete'&&hasIssue($r,'placeholder','seo_description'),'translation placeholder blocks publication');
    $shortSource=$source;$shortSource['title']='Samer';$shortTarget=$target;$shortTarget['title']='Samer';$r=$validator->inspect($shortSource,$shortTarget,'ar','en',[],true);$ambiguous=null;foreach($r['issues'] as $issue)if(($issue['type']??'')==='copied_source'&&($issue['field']??'')==='title'){$ambiguous=$issue;break;}translationExpect($ambiguous&&$ambiguous['severity']==='ambiguous','proper name is reviewable rather than a confirmed error');
    $resolutions=[$ambiguous['key']=>['reason'=>'اسم الشخصية محفوظ كما هو في جميع اللغات.','source_hash'=>$r['source_hash'],'translation_hash'=>$r['translation_hash']]];$resolved=$validator->inspect($shortSource,$shortTarget,'ar','en',$resolutions,true);translationExpect($resolved['blocking']===0&&$resolved['state']==='passed','documented intentional proper name can pass');
    $corrected=$validator->inspect($source,$target,'ar','en',[],true);translationExpect($corrected['state']==='passed','correction followed by revalidation passes');

    $suffix=bin2hex(random_bytes(4));$userId=Database::insert("INSERT INTO users(name,username,email,password_hash,role,status) VALUES(?,?,?,?,'admin','active')",['مدقق ترجمة','validator'.$suffix,'validator'.$suffix.'@example.invalid',password_hash('temporary-password',PASSWORD_DEFAULT)]);
    $articleId=Database::insert("INSERT INTO articles(author_id,status) VALUES(?,'published')",[$userId]);
    Database::insert("INSERT INTO article_translations(article_id,locale,title,slug,excerpt,content,image_alt,image_caption,seo_description,og_description,status,review_state) VALUES(?,?,?,?,?,?,?,?,?,?,'published','approved')",[$articleId,'ar',$source['title'],'source-'.$suffix,$source['excerpt'],$source['content'],$source['image_alt'],$source['image_caption'],$source['seo_description'],$source['og_description']]);
    Database::insert("INSERT INTO article_translations(article_id,locale,title,slug,excerpt,content,image_alt,image_caption,seo_description,og_description,status,review_state) VALUES(?,?,?,?,?,?,?,?,?,?,'draft','review')",[$articleId,'en',$target['title'],'target-'.$suffix,$target['excerpt'],$target['content'],$target['image_alt'],$target['image_caption'],$target['seo_description'],$target['og_description']]);
    $persisted=$validator->validateArticle($articleId,'en',$userId,true);translationExpect($persisted['state']==='passed'&&Database::one("SELECT completeness_state FROM article_translations WHERE article_id=? AND locale='en'",[$articleId])['completeness_state']==='passed','successful validation report persists');
    Database::exec("UPDATE article_translations SET content=? WHERE article_id=? AND locale='en'",[$source['content'],$articleId]);$validator->invalidate($articleId,'en');$blocked=$validator->validateArticle($articleId,'en',$userId,true);translationExpect($blocked['blocking']>0&&Database::one("SELECT status FROM article_translations WHERE article_id=? AND locale='en'",[$articleId])['status']==='draft','changed untranslated content invalidates approval and remains unpublished');
    Database::exec("UPDATE article_translations SET content=? WHERE article_id=? AND locale='en'",[$target['content'],$articleId]);$revalidated=$validator->validateArticle($articleId,'en',$userId,true);if(!$revalidated['blocking'])Database::exec("UPDATE article_translations SET status='published',review_state='approved' WHERE article_id=? AND locale='en'",[$articleId]);translationExpect($revalidated['state']==='passed'&&Database::one("SELECT status FROM article_translations WHERE article_id=? AND locale='en'",[$articleId])['status']==='published','publication succeeds only after corrected server-side validation');
}catch(Throwable $error){$failures[]=$error->getMessage();echo 'ERROR: '.$error->getMessage()."\n";}
finally{if($pdo->inTransaction())$pdo->rollBack();}
$report=['passed'=>$passed,'failed'=>count($failures),'failures'=>$failures,'limitations'=>['احتمال وجود نتائج إيجابية كاذبة مع الأسماء والاقتباسات والمصطلحات، ولهذا تتطلب توثيقًا بشريًا.','قد لا تُكتشف عبارة قصيرة جدًا إذا لم تطابق الأصل ولم تحمل مؤشرًا كتابيًا أو لغويًا واضحًا.','تمييز الإنجليزية والفرنسية والتركية يعتمد على قرائن معجمية محدودة ولا يدّعي تحديدًا لغويًا مثاليًا.'],'executed_at'=>date(DATE_ATOM),'transaction_rolled_back'=>true];
file_put_contents(BASE_PATH.'/storage/translation-completeness-tests.json',json_encode($report,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));echo json_encode($report,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)."\n";exit($failures?1:0);
